    console.log("DOWN");
} else if (N === 1) {
    console.log(-1);
} else {
    const last = a[N - 1];
    const prev = a[N - 2];

    if (prev > last && last !== 0) {
        console.log("DOWN");
    } else if (prev < last && last !== 15) {
        console.log("UP");
    } else if (last === 0) {
        console.log("UP");
    } else if (last === 15) {
        console.log("DOWN");
    }
